css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .72); height: var(--loader-size); position: relative; }
.loader .trellis { position: absolute; left: 30%; bottom: 4%; width: 40%; height: 92%; border-radius: 4px; background: repeating-linear-gradient(color-mix(in srgb, var(--accent) 20%, transparent) 0 6%, transparent 0 18%), color-mix(in srgb, var(--accent) 10%, transparent); }
.loader .stem { position: absolute; left: 45%; bottom: 4%; width: 10%; height: 0; border-radius: 5px; background: linear-gradient(var(--accent-2), var(--accent)); animation: vine-rise calc(var(--loader-speed) * 3.2) ease-in-out infinite; }
.loader span { position: absolute; width: 30%; height: 12%; background: var(--accent-2); transform: scale(0); animation: vine-leaf calc(var(--loader-speed) * 3.2) ease-out infinite; }
.loader span:nth-of-type(1) { left: 55%; bottom: 20%; border-radius: 60% 6% 60% 6%; transform-origin: 0 50%; animation-delay: calc(var(--loader-speed) * .5); }
.loader span:nth-of-type(2) { right: 55%; bottom: 38%; border-radius: 6% 60% 6% 60%; transform-origin: 100% 50%; animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-of-type(3) { left: 55%; bottom: 56%; border-radius: 60% 6% 60% 6%; transform-origin: 0 50%; animation-delay: calc(var(--loader-speed) * 1.1); }
.loader span:nth-of-type(4) { right: 55%; bottom: 74%; border-radius: 6% 60% 6% 60%; transform-origin: 100% 50%; animation-delay: calc(var(--loader-speed) * 1.4); }
@keyframes vine-rise { 0%, 4% { height: 0; } 52%, 78% { height: 88%; } 96%, 100% { height: 0; } }
@keyframes vine-leaf { 0%, 12% { transform: scale(0); opacity: 0; } 32%, 62% { transform: scale(1); opacity: 1; } 82%, 100% { transform: scale(0); opacity: 0; } }
